    {"name": "EstimationPro AI", "url": "https://estimationpro.ai/", "relationship": "direct", "pricing": "Free first estimate, no credit card", "evidence": "Turns job site photos, voice notes, and measurements into line-item estimates in under 2 minutes for HVAC, roofing, painting, electrical, etc."},
    {"name": "CostSnap", "url": "https://costsnap.app/", "relationship": "direct", "pricing": "Freemium with paid Smart/Unlimited tiers", "evidence": "AI estimating and quoting app: photo estimates, client portal, leads, AI call centre, for 12+ trades."},
    {"name": "QuotrPro", "url": "https://quotr.pro/", "relationship": "direct", "pricing": "3-day free trial, no card required", "evidence": "Snap photos, get priced estimate using real local material and labor prices by zip code; 500+ contractors using it."},
